/* WellStream Platform — Global Styles */
:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --dark-gray: #3C424B;
  --text-primary: #E8ECF1;
  --text-secondary: #A0AEBB;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-green: #6CC24A;
  --brand-navy: #15295A;
  --white: #FFFFFF;
  --border-color: rgba(255,255,255,0.08);
  --card-bg: rgba(27,40,56,0.6);
  --radius: 8px;
  --radius-lg: 12px;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--navy);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }

img { max-width: 100%; display: block; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13,27,42,0.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px; height: 72px;
}
.nav-inner {
  max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; height: 100%;
}
.nav-logo {
  font-size: 1.35rem; font-weight: 700; color: var(--white); letter-spacing: -0.02em;
}
.nav-logo span { color: var(--accent-blue); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links > li { position: relative; }
.nav-links > li > a {
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  padding: 8px 0; transition: color var(--transition);
}
.nav-links > li > a:hover { color: var(--white); }

.nav-dropdown { position: relative; }
.nav-dropdown > a::after {
  content: ''; display: inline-block; width: 0; height: 0;
  border-left: 4px solid transparent; border-right: 4px solid transparent;
  border-top: 4px solid currentColor; margin-left: 6px; vertical-align: middle;
}
.dropdown-menu {
  position: absolute; top: 100%; left: 0; min-width: 200px;
  background: var(--navy-mid); border: 1px solid var(--border-color);
  border-radius: var(--radius); padding: 8px 0;
  opacity: 0; visibility: hidden; transform: translateY(8px);
  transition: all var(--transition); box-shadow: 0 12px 32px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: 10px 20px; color: var(--text-secondary);
  font-size: 0.875rem; transition: all var(--transition);
}
.dropdown-menu a:hover { color: var(--white); background: rgba(0,180,216,0.1); }

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.9rem; cursor: pointer; border: none; transition: all var(--transition);
  text-decoration: none;
}
.btn-primary {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  color: var(--white); box-shadow: 0 4px 16px rgba(0,180,216,0.3);
}
.btn-primary:hover {
  transform: translateY(-2px); box-shadow: 0 6px 24px rgba(0,180,216,0.45);
  color: var(--white);
}
.btn-secondary {
  background: transparent; border: 1px solid var(--accent-blue); color: var(--accent-blue);
}
.btn-secondary:hover {
  background: rgba(0,180,216,0.1); transform: translateY(-2px); color: var(--accent-blue);
}
.btn-nav {
  padding: 10px 22px; font-size: 0.85rem; border-radius: 6px;
}

.hamburger {
  display: none; flex-direction: column; gap: 5px; cursor: pointer;
  background: none; border: none; padding: 4px;
}
.hamburger span {
  display: block; width: 24px; height: 2px; background: var(--text-primary);
  transition: all var(--transition);
}

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px; text-align: center;
  background: linear-gradient(180deg, var(--navy) 0%, var(--navy-mid) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(0,180,216,0.08) 0%, transparent 60%);
  pointer-events: none;
}
.hero-label {
  font-size: 0.8rem; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--accent-blue); margin-bottom: 20px;
}
.hero h1 {
  font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1;
  color: var(--white); max-width: 800px; margin: 0 auto 24px;
  letter-spacing: -0.03em;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary); max-width: 640px;
  margin: 0 auto 40px; line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ===== SECTIONS ===== */
.section {
  padding: 100px 0;
}
.section-alt {
  background: var(--navy-mid);
}
.section-label {
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--accent-blue); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 700; color: var(--white);
  margin-bottom: 16px; letter-spacing: -0.02em;
}
.section-desc {
  font-size: 1.05rem; color: var(--text-secondary); max-width: 680px; line-height: 1.7;
}
.section-header { margin-bottom: 60px; }
.section-header.center { text-align: center; }
.section-header.center .section-desc { margin-left: auto; margin-right: auto; }

/* ===== CARDS ===== */
.card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 32px;
  transition: all var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}
.card-icon {
  width: 48px; height: 48px; border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.15));
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; color: var(--accent-blue); font-size: 1.25rem;
}
.card h3 {
  font-size: 1.1rem; font-weight: 600; color: var(--white); margin-bottom: 10px;
}
.card p { font-size: 0.925rem; color: var(--text-secondary); line-height: 1.6; }

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ===== TABS ===== */
.tabs { margin-bottom: 40px; }
.tab-nav {
  display: flex; gap: 4px; border-bottom: 1px solid var(--border-color);
  overflow-x: auto; padding-bottom: 0;
}
.tab-btn {
  padding: 14px 24px; font-size: 0.9rem; font-weight: 600;
  color: var(--text-secondary); background: transparent; border: none;
  cursor: pointer; position: relative; white-space: nowrap;
  transition: color var(--transition);
}
.tab-btn::after {
  content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
  height: 2px; background: var(--accent-blue);
  transform: scaleX(0); transition: transform var(--transition);
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--accent-blue); }
.tab-btn.active::after { transform: scaleX(1); }

.tab-panel { display: none; animation: fadeTab 0.4s ease; }
.tab-panel.active { display: block; }
@keyframes fadeTab { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== ACCORDION ===== */
.accordion-item {
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  margin-bottom: 12px; overflow: hidden; transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.2); }
.accordion-header {
  width: 100%; padding: 20px 28px; display: flex; align-items: center;
  justify-content: space-between; background: var(--card-bg); border: none;
  color: var(--white); font-size: 1.05rem; font-weight: 600;
  cursor: pointer; transition: background var(--transition);
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-chevron {
  width: 20px; height: 20px; transition: transform var(--transition);
  color: var(--accent-blue); flex-shrink: 0;
}
.accordion-item.open .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease;
}
.accordion-item.open .accordion-body { max-height: 400px; }
.accordion-body-inner {
  padding: 0 28px 24px; color: var(--text-secondary); font-size: 0.95rem; line-height: 1.7;
}

/* ===== STATS ===== */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.stat-item { text-align: center; }
.stat-circle {
  width: 140px; height: 140px; border-radius: 50%; margin: 0 auto 20px;
  display: flex; align-items: center; justify-content: center; flex-direction: column;
  background: conic-gradient(var(--accent-blue) var(--pct, 0%), rgba(255,255,255,0.05) var(--pct, 0%));
  position: relative;
}
.stat-circle::before {
  content: ''; position: absolute; inset: 6px; border-radius: 50%; background: var(--navy-mid);
}
.stat-circle-inner {
  position: relative; z-index: 1; text-align: center;
}
.stat-value {
  font-size: 2rem; font-weight: 800; color: var(--accent-blue); line-height: 1;
}
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary); margin-top: 8px;
  max-width: 160px; line-height: 1.4;
}

/* ===== TIMELINE ===== */
.timeline-items { display: flex; flex-direction: column; gap: 24px; }
.timeline-item {
  display: flex; align-items: center; gap: 24px;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 24px 28px;
}
.timeline-duration {
  font-size: 1.5rem; font-weight: 800; color: var(--accent-blue);
  white-space: nowrap; min-width: 140px;
}
.timeline-info { flex: 1; }
.timeline-info p { color: var(--text-secondary); font-size: 0.95rem; margin-bottom: 12px; }
.progress-bar {
  height: 6px; background: rgba(255,255,255,0.06); border-radius: 3px; overflow: hidden;
}
.progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1s ease;
}

/* ===== TESTIMONIALS ===== */
.testimonial-carousel { position: relative; overflow: hidden; }
.testimonial-track {
  display: flex; transition: transform 0.5s ease;
}
.testimonial-card {
  flex: 0 0 100%; padding: 40px; background: var(--card-bg);
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
}
.testimonial-card blockquote {
  font-size: 1.15rem; color: var(--text-primary); line-height: 1.8;
  font-style: italic; margin-bottom: 20px;
}
.testimonial-card cite {
  font-size: 0.9rem; color: var(--accent-blue); font-style: normal; font-weight: 600;
}
.carousel-dots {
  display: flex; justify-content: center; gap: 8px; margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; border: none; cursor: pointer;
  background: rgba(255,255,255,0.15); transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ===== DIAGRAM ===== */
.diagram-wrapper {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 48px; position: relative;
}
.diagram-center {
  text-align: center; margin-bottom: 40px;
}
.diagram-center h3 {
  font-size: 1.3rem; font-weight: 700; color: var(--accent-blue); margin-bottom: 8px;
}
.diagram-center p { color: var(--text-secondary); font-size: 0.95rem; }
.diagram-pillars {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
}
.diagram-pillar {
  text-align: center; padding: 32px 20px;
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  background: rgba(0,180,216,0.03); position: relative;
  transition: all var(--transition);
}
.diagram-pillar:hover {
  border-color: rgba(0,180,216,0.3); background: rgba(0,180,216,0.06);
}
.diagram-pillar-icon {
  width: 64px; height: 64px; border-radius: 50%; margin: 0 auto 16px;
  background: linear-gradient(135deg, rgba(0,180,216,0.2), rgba(0,119,182,0.2));
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--accent-blue);
}
.diagram-pillar h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 8px; }
.diagram-pillar p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.5; }
.diagram-connectors {
  position: absolute; top: 50%; left: 0; right: 0;
  display: flex; justify-content: center; gap: 0;
  pointer-events: none;
}

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(135deg, var(--brand-navy), var(--navy-mid));
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  padding: 40px 48px; display: flex; align-items: center;
  justify-content: space-between; flex-wrap: wrap; gap: 24px;
}
.featured-banner h3 {
  font-size: 1.5rem; font-weight: 700; color: var(--white);
}
.featured-banner .badge {
  display: inline-block; background: rgba(0,180,216,0.15); color: var(--accent-blue);
  padding: 4px 12px; border-radius: 4px; font-size: 0.8rem; font-weight: 600;
  margin-bottom: 8px; letter-spacing: 0.05em;
}

/* ===== CULTURE / CTA BLOCKS ===== */
.cta-block {
  padding: 80px; text-align: center;
  background: linear-gradient(135deg, var(--brand-navy), var(--navy-mid));
  border-radius: var(--radius-lg); border: 1px solid var(--border-color);
}
.cta-block h2 {
  font-size: 2rem; font-weight: 700; color: var(--white); margin-bottom: 16px;
}
.cta-block p {
  font-size: 1.05rem; color: var(--text-secondary); max-width: 640px;
  margin: 0 auto 32px; line-height: 1.7;
}

/* ===== FORM ===== */
.form-wrapper {
  max-width: 720px; margin: 0 auto;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 48px;
}
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 600; color: var(--text-secondary);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px; border-radius: var(--radius);
  border: 1px solid var(--border-color); background: rgba(13,27,42,0.8);
  color: var(--text-primary); font-size: 0.95rem; font-family: inherit;
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none; border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.15);
}
.form-group input.error,
.form-group select.error { border-color: #e74c3c; }
.form-error {
  font-size: 0.8rem; color: #e74c3c; margin-top: 4px; display: none;
}
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit { margin-top: 24px; text-align: center; }
.form-success {
  display: none; text-align: center; padding: 40px;
}
.form-success h3 { font-size: 1.5rem; color: var(--accent-green); margin-bottom: 12px; }
.form-success p { color: var(--text-secondary); }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy); border-top: 1px solid var(--border-color);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 48px;
  margin-bottom: 48px;
}
.footer-brand p { color: var(--text-secondary); font-size: 0.9rem; margin-top: 12px; line-height: 1.6; }
.footer-col h4 {
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.15em; color: var(--text-secondary); margin-bottom: 16px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--text-secondary); font-size: 0.9rem; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid var(--border-color); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.85rem; color: var(--text-secondary);
}
.footer-login a { margin-left: 16px; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--navy-mid); border-top: 1px solid var(--border-color);
  padding: 20px 24px; display: flex; align-items: center;
  justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.4);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.9rem; color: var(--text-secondary); max-width: 600px; }
.cookie-actions { display: flex; gap: 12px; }
.cookie-actions button {
  padding: 10px 20px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.85rem; cursor: pointer; border: none; transition: all var(--transition);
}
.cookie-accept {
  background: var(--accent-blue); color: var(--white);
}
.cookie-accept:hover { background: var(--accent-blue-dark); }
.cookie-decline {
  background: transparent; border: 1px solid var(--border-color); color: var(--text-secondary);
}
.cookie-decline:hover { border-color: var(--text-secondary); color: var(--white); }

/* ===== SECURITY FEATURE CARDS ===== */
.security-card {
  display: flex; gap: 20px; align-items: flex-start;
  padding: 28px; background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); margin-bottom: 16px;
  transition: all var(--transition);
}
.security-card:hover { border-color: rgba(0,180,216,0.3); }
.security-icon {
  flex-shrink: 0; width: 48px; height: 48px; border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.15));
  display: flex; align-items: center; justify-content: center;
  color: var(--accent-blue); font-size: 1.2rem;
}
.security-card h3 { font-size: 1.05rem; font-weight: 600; color: var(--white); margin-bottom: 6px; }
.security-card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

/* ===== ETL BENEFIT LIST ===== */
.benefit-item {
  display: flex; gap: 16px; align-items: flex-start; margin-bottom: 20px;
}
.benefit-check {
  flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%;
  background: rgba(108,194,74,0.15); display: flex; align-items: center;
  justify-content: center; color: var(--accent-green); font-size: 0.9rem; margin-top: 2px;
}
.benefit-item h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 4px; }
.benefit-item p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.5; }

/* ===== SUPPORT CONTACT ===== */
.support-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.support-card {
  text-align: center; padding: 32px;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
}
.support-card h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 8px; }
.support-card p { font-size: 0.875rem; color: var(--text-secondary); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(3, 1fr); gap: 24px; }
  .diagram-pillars { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .site-header { padding: 0 16px; }
  .nav-links {
    display: none; position: fixed; top: 72px; left: 0; right: 0;
    background: var(--navy-mid); flex-direction: column; padding: 24px;
    gap: 16px; border-bottom: 1px solid var(--border-color);
  }
  .nav-links.open { display: flex; }
  .hamburger { display: flex; }
  .dropdown-menu {
    position: static; opacity: 1; visibility: visible; transform: none;
    box-shadow: none; background: rgba(0,0,0,0.2); border: none;
    margin-top: 8px; display: none;
  }
  .nav-dropdown.open .dropdown-menu { display: block; }
  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 2rem; }
  .section { padding: 60px 0; }
  .grid-2, .grid-3, .grid-6 { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .diagram-pillars { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .form-grid { grid-template-columns: 1fr; }
  .featured-banner { padding: 28px; flex-direction: column; text-align: center; }
  .cta-block { padding: 48px 24px; }
  .timeline-item { flex-direction: column; align-items: flex-start; }
  .support-grid { grid-template-columns: 1fr; }
  .tab-nav { gap: 0; }
  .tab-btn { padding: 12px 16px; font-size: 0.85rem; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 1.65rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .stat-circle { width: 120px; height: 120px; }
  .stat-value { font-size: 1.6rem; }
}

/* WellStream Platform — Global Styles */
:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --dark-gray: #3C424B;
  --text-primary: #E8ECF1;
  --text-secondary: #A0AEBB;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-green: #6CC24A;
  --brand-navy: #15295A;
  --white: #FFFFFF;
  --border-color: rgba(255,255,255,0.08);
  --card-bg: rgba(27,40,56,0.6);
  --radius: 8px;
  --radius-lg: 12px;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--navy);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }

img { max-width: 100%; display: block; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13,27,42,0.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px; height: 72px;
}
.nav-inner {
  max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; height: 100%;
}
.nav-logo {
  font-size: 1.35rem; font-weight: 700; color: var(--white); letter-spacing: -0.02em;
}
.nav-logo span { color: var(--accent-blue); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links > li { position: relative; }
.nav-links > li > a {
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  padding: 8px 0; transition: color var(--transition);
}
.nav-links > li > a:hover { color: var(--white); }

.nav-dropdown { position: relative; }
.nav-dropdown > a::after {
  content: ''; display: inline-block; width: 0; height: 0;
  border-left: 4px solid transparent; border-right: 4px solid transparent;
  border-top: 4px solid currentColor; margin-left: 6px; vertical-align: middle;
}
.dropdown-menu {
  position: absolute; top: 100%; left: 0; min-width: 200px;
  background: var(--navy-mid); border: 1px solid var(--border-color);
  border-radius: var(--radius); padding: 8px 0;
  opacity: 0; visibility: hidden; transform: translateY(8px);
  transition: all var(--transition); box-shadow: 0 12px 32px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: 10px 20px; color: var(--text-secondary);
  font-size: 0.875rem; transition: all var(--transition);
}
.dropdown-menu a:hover { color: var(--white); background: rgba(0,180,216,0.1); }

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.9rem; cursor: pointer; border: none; transition: all var(--transition);
  text-decoration: none;
}
.btn-primary {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  color: var(--white); box-shadow: 0 4px 16px rgba(0,180,216,0.3);
}
.btn-primary:hover {
  transform: translateY(-2px); box-shadow: 0 6px 24px rgba(0,180,216,0.45);
  color: var(--white);
}
.btn-secondary {
  background: transparent; border: 1px solid var(--accent-blue); color: var(--accent-blue);
}
.btn-secondary:hover {
  background: rgba(0,180,216,0.1); transform: translateY(-2px); color: var(--accent-blue);
}
.btn-nav {
  padding: 10px 22px; font-size: 0.85rem; border-radius: 6px;
}

.hamburger {
  display: none; flex-direction: column; gap: 5px; cursor: pointer;
  background: none; border: none; padding: 4px;
}
.hamburger span {
  display: block; width: 24px; height: 2px; background: var(--text-primary);
  transition: all var(--transition);
}

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px; text-align: center;
  background: linear-gradient(180deg, var(--navy) 0%, var(--navy-mid) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(0,180,216,0.08) 0%, transparent 60%);
  pointer-events: none;
}
.hero-label {
  font-size: 0.8rem; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--accent-blue); margin-bottom: 20px;
}
.hero h1 {
  font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1;
  color: var(--white); max-width: 800px; margin: 0 auto 24px;
  letter-spacing: -0.03em;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary); max-width: 640px;
  margin: 0 auto 40px; line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ===== SECTIONS ===== */
.section {
  padding: 100px 0;
}
.section-alt {
  background: var(--navy-mid);
}
.section-label {
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--accent-blue); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 700; color: var(--white);
  margin-bottom: 16px; letter-spacing: -0.02em;
}
.section-desc {
  font-size: 1.05rem; color: var(--text-secondary); max-width: 680px; line-height: 1.7;
}
.section-header { margin-bottom: 60px; }
.section-header.center { text-align: center; }
.section-header.center .section-desc { margin-left: auto; margin-right: auto; }

/* ===== CARDS ===== */
.card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 32px;
  transition: all var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}
.card-icon {
  width: 48px; height: 48px; border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.15));
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; color: var(--accent-blue); font-size: 1.25rem;
}
.card h3 {
  font-size: 1.1rem; font-weight: 600; color: var(--white); margin-bottom: 10px;
}
.card p { font-size: 0.925rem; color: var(--text-secondary); line-height: 1.6; }

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ===== TABS ===== */
.tabs { margin-bottom: 40px; }
.tab-nav {
  display: flex; gap: 4px; border-bottom: 1px solid var(--border-color);
  overflow-x: auto; padding-bottom: 0;
}
.tab-btn {
  padding: 14px 24px; font-size: 0.9rem; font-weight: 600;
  color: var(--text-secondary); background: transparent; border: none;
  cursor: pointer; position: relative; white-space: nowrap;
  transition: color var(--transition);
}
.tab-btn::after {
  content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
  height: 2px; background: var(--accent-blue);
  transform: scaleX(0); transition: transform var(--transition);
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--accent-blue); }
.tab-btn.active::after { transform: scaleX(1); }

.tab-panel { display: none; animation: fadeTab 0.4s ease; }
.tab-panel.active { display: block; }
@keyframes fadeTab { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== ACCORDION ===== */
.accordion-item {
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  margin-bottom: 12px; overflow: hidden; transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.2); }
.accordion-header {
  width: 100%; padding: 20px 28px; display: flex; align-items: center;
  justify-content: space-between; background: var(--card-bg); border: none;
  color: var(--white); font-size: 1.05rem; font-weight: 600;
  cursor: pointer; transition: background var(--transition);
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-chevron {
  width: 20px; height: 20px; transition: transform var(--transition);
  color: var(--accent-blue); flex-shrink: 0;
}
.accordion-item.open .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease;
}
.accordion-item.open .accordion-body { max-height: 400px; }
.accordion-body-inner {
  padding: 0 28px 24px; color: var(--text-secondary); font-size: 0.95rem; line-height: 1.7;
}

/* ===== STATS ===== */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.stat-item { text-align: center; }
.stat-circle {
  width: 140px; height: 140px; border-radius: 50%; margin: 0 auto 20px;
  display: flex; align-items: center; justify-content: center; flex-direction: column;
  background: conic-gradient(var(--accent-blue) var(--pct, 0%), rgba(255,255,255,0.05) var(--pct, 0%));
  position: relative;
}
.stat-circle::before {
  content: ''; position: absolute; inset: 6px; border-radius: 50%; background: var(--navy-mid);
}
.stat-circle-inner {
  position: relative; z-index: 1; text-align: center;
}
.stat-value {
  font-size: 2rem; font-weight: 800; color: var(--accent-blue); line-height: 1;
}
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary); margin-top: 8px;
  max-width: 160px; line-height: 1.4;
}

/* ===== TIMELINE ===== */
.timeline-items { display: flex; flex-direction: column; gap: 24px; }
.timeline-item {
  display: flex; align-items: center; gap: 24px;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 24px 28px;
}
.timeline-duration {
  font-size: 1.5rem; font-weight: 800; color: var(--accent-blue);
  white-space: nowrap; min-width: 140px;
}
.timeline-info { flex: 1; }
.timeline-info p { color: var(--text-secondary); font-size: 0.95rem; margin-bottom: 12px; }
.progress-bar {
  height: 6px; background: rgba(255,255,255,0.06); border-radius: 3px; overflow: hidden;
}
.progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1s ease;
}

/* ===== TESTIMONIALS ===== */
.testimonial-carousel { position: relative; overflow: hidden; }
.testimonial-track {
  display: flex; transition: transform 0.5s ease;
}
.testimonial-card {
  flex: 0 0 100%; padding: 40px; background: var(--card-bg);
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
}
.testimonial-card blockquote {
  font-size: 1.15rem; color: var(--text-primary); line-height: 1.8;
  font-style: italic; margin-bottom: 20px;
}
.testimonial-card cite {
  font-size: 0.9rem; color: var(--accent-blue); font-style: normal; font-weight: 600;
}
.carousel-dots {
  display: flex; justify-content: center; gap: 8px; margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; border: none; cursor: pointer;
  background: rgba(255,255,255,0.15); transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ===== DIAGRAM ===== */
.diagram-wrapper {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 48px; position: relative;
}
.diagram-center {
  text-align: center; margin-bottom: 40px;
}
.diagram-center h3 {
  font-size: 1.3rem; font-weight: 700; color: var(--accent-blue); margin-bottom: 8px;
}
.diagram-center p { color: var(--text-secondary); font-size: 0.95rem; }
.diagram-pillars {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
}
.diagram-pillar {
  text-align: center; padding: 32px 20px;
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  background: rgba(0,180,216,0.03); position: relative;
  transition: all var(--transition);
}
.diagram-pillar:hover {
  border-color: rgba(0,180,216,0.3); background: rgba(0,180,216,0.06);
}
.diagram-pillar-icon {
  width: 64px; height: 64px; border-radius: 50%; margin: 0 auto 16px;
  background: linear-gradient(135deg, rgba(0,180,216,0.2), rgba(0,119,182,0.2));
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--accent-blue);
}
.diagram-pillar h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 8px; }
.diagram-pillar p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.5; }
.diagram-connectors {
  position: absolute; top: 50%; left: 0; right: 0;
  display: flex; justify-content: center; gap: 0;
  pointer-events: none;
}

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(135deg, var(--brand-navy), var(--navy-mid));
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  padding: 40px 48px; display: flex; align-items: center;
  justify-content: space-between; flex-wrap: wrap; gap: 24px;
}
.featured-banner h3 {
  font-size: 1.5rem; font-weight: 700; color: var(--white);
}
.featured-banner .badge {
  display: inline-block; background: rgba(0,180,216,0.15); color: var(--accent-blue);
  padding: 4px 12px; border-radius: 4px; font-size: 0.8rem; font-weight: 600;
  margin-bottom: 8px; letter-spacing: 0.05em;
}

/* ===== CULTURE / CTA BLOCKS ===== */
.cta-block {
  padding: 80px; text-align: center;
  background: linear-gradient(135deg, var(--brand-navy), var(--navy-mid));
  border-radius: var(--radius-lg); border: 1px solid var(--border-color);
}
.cta-block h2 {
  font-size: 2rem; font-weight: 700; color: var(--white); margin-bottom: 16px;
}
.cta-block p {
  font-size: 1.05rem; color: var(--text-secondary); max-width: 640px;
  margin: 0 auto 32px; line-height: 1.7;
}

/* ===== FORM ===== */
.form-wrapper {
  max-width: 720px; margin: 0 auto;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 48px;
}
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 600; color: var(--text-secondary);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px; border-radius: var(--radius);
  border: 1px solid var(--border-color); background: rgba(13,27,42,0.8);
  color: var(--text-primary); font-size: 0.95rem; font-family: inherit;
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none; border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.15);
}
.form-group input.error,
.form-group select.error { border-color: #e74c3c; }
.form-error {
  font-size: 0.8rem; color: #e74c3c; margin-top: 4px; display: none;
}
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit { margin-top: 24px; text-align: center; }
.form-success {
  display: none; text-align: center; padding: 40px;
}
.form-success h3 { font-size: 1.5rem; color: var(--accent-green); margin-bottom: 12px; }
.form-success p { color: var(--text-secondary); }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy); border-top: 1px solid var(--border-color);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 48px;
  margin-bottom: 48px;
}
.footer-brand p { color: var(--text-secondary); font-size: 0.9rem; margin-top: 12px; line-height: 1.6; }
.footer-col h4 {
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.15em; color: var(--text-secondary); margin-bottom: 16px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--text-secondary); font-size: 0.9rem; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid var(--border-color); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.85rem; color: var(--text-secondary);
}
.footer-login a { margin-left: 16px; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--navy-mid); border-top: 1px solid var(--border-color);
  padding: 20px 24px; display: flex; align-items: center;
  justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.4);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.9rem; color: var(--text-secondary); max-width: 600px; }
.cookie-actions { display: flex; gap: 12px; }
.cookie-actions button {
  padding: 10px 20px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.85rem; cursor: pointer; border: none; transition: all var(--transition);
}
.cookie-accept {
  background: var(--accent-blue); color: var(--white);
}
.cookie-accept:hover { background: var(--accent-blue-dark); }
.cookie-decline {
  background: transparent; border: 1px solid var(--border-color); color: var(--text-secondary);
}
.cookie-decline:hover { border-color: var(--text-secondary); color: var(--white); }

/* ===== SECURITY FEATURE CARDS ===== */
.security-card {
  display: flex; gap: 20px; align-items: flex-start;
  padding: 28px; background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); margin-bottom: 16px;
  transition: all var(--transition);
}
.security-card:hover { border-color: rgba(0,180,216,0.3); }
.security-icon {
  flex-shrink: 0; width: 48px; height: 48px; border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.15));
  display: flex; align-items: center; justify-content: center;
  color: var(--accent-blue); font-size: 1.2rem;
}
.security-card h3 { font-size: 1.05rem; font-weight: 600; color: var(--white); margin-bottom: 6px; }
.security-card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

/* ===== ETL BENEFIT LIST ===== */
.benefit-item {
  display: flex; gap: 16px; align-items: flex-start; margin-bottom: 20px;
}
.benefit-check {
  flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%;
  background: rgba(108,194,74,0.15); display: flex; align-items: center;
  justify-content: center; color: var(--accent-green); font-size: 0.9rem; margin-top: 2px;
}
.benefit-item h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 4px; }
.benefit-item p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.5; }

/* ===== SUPPORT CONTACT ===== */
.support-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.support-card {
  text-align: center; padding: 32px;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
}
.support-card h4 { font-size: 1rem; font-weight: 600; color: var(--white); margin-bottom: 8px; }
.support-card p { font-size: 0.875rem; color: var(--text-secondary); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(3, 1fr); gap: 24px; }
  .diagram-pillars { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .site-header { padding: 0 16px; }
  .nav-links {
    display: none; position: fixed; top: 72px; left: 0; right: 0;
    background: var(--navy-mid); flex-direction: column; padding: 24px;
    gap: 16px; border-bottom: 1px solid var(--border-color);
  }
  .nav-links.open { display: flex; }
  .hamburger { display: flex; }
  .dropdown-menu {
    position: static; opacity: 1; visibility: visible; transform: none;
    box-shadow: none; background: rgba(0,0,0,0.2); border: none;
    margin-top: 8px; display: none;
  }
  .nav-dropdown.open .dropdown-menu { display: block; }
  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 2rem; }
  .section { padding: 60px 0; }
  .grid-2, .grid-3, .grid-6 { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .diagram-pillars { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .form-grid { grid-template-columns: 1fr; }
  .featured-banner { padding: 28px; flex-direction: column; text-align: center; }
  .cta-block { padding: 48px 24px; }
  .timeline-item { flex-direction: column; align-items: flex-start; }
  .support-grid { grid-template-columns: 1fr; }
  .tab-nav { gap: 0; }
  .tab-btn { padding: 12px 16px; font-size: 0.85rem; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 1.65rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .stat-circle { width: 120px; height: 120px; }
  .stat-value { font-size: 1.6rem; }
}

